  Object.assign(DICT,{"Trade-In Record":{"es":"Registro de intercambio","pt":"Registro de troca","tr":"Takas Kayıt Formu"},"Fill out and print a trade inspection worksheet.":{"es":"Complete e imprima una hoja de inspección.","pt":"Preencha e imprima uma ficha de inspeção.","tr":"Takas kontrol formunu doldurun ve yazdırın."},"Fill out an inspection record now or later. Choose a trade phone, document its condition and the promotional quote, then print.":{"es":"Cree un registro de inspección cuando lo necesite.","pt":"Crie uma ficha de inspeção quando precisar.","tr":"Gerektiğinde takas kontrol kaydı oluşturun."},"Fill out a print-only trade-in inspection record.":{"es":"Complete un registro para imprimir.","pt":"Preencha uma ficha para impressão.","tr":"Yazdırılacak takas formunu doldurun."},"Standalone":{"es":"Independiente","pt":"Independente","tr":"Bağımsız"},"Print Only":{"es":"Solo impresión","pt":"Somente impressão","tr":"Yalnızca yazdırma"},"Purchase / quote date":{"es":"Fecha de compra o cotización","pt":"Data da compra ou cotação","tr":"Satış / teklif tarihi"},"Account holder name":{"es":"Nombre del titular de la cuenta","pt":"Nome do titular da conta","tr":"Hesap sahibinin adı"},"Trade-in phone number":{"es":"Número del teléfono entregado","pt":"Número do telefone usado","tr":"Takas telefon numarası"},"Trade-in IMEI":{"es":"IMEI del teléfono entregado","pt":"IMEI do telefone usado","tr":"Takas IMEI numarası"},"Phone being traded in":{"es":"Teléfono que se entrega","pt":"Celular usado na troca","tr":"Takas edilen telefon"},"Storage / capacity":{"es":"Almacenamiento / capacidad","pt":"Armazenamento / capacidade","tr":"Depolama / kapasite"},"AT&T plan":{"es":"Plan de AT&T","pt":"Plano AT&T","tr":"AT&T tarifesi"},"Device condition — select Yes or No for each":{"es":"Estado del equipo: seleccione Sí o No","pt":"Condição do aparelho: selecione Sim ou Não","tr":"Cihaz durumu: Evet veya Hayır seçin"},"Powers on and functions?":{"es":"¿Enciende y funciona?","pt":"Liga e funciona?","tr":"Açılıyor ve çalışıyor mu?"},"Activation Lock / Find My turned off?":{"es":"¿Bloqueo de activación / Buscar desactivado?","pt":"Bloqueio de ativação / Buscar desativado?","tr":"Etkinleştirme kilidi / Bul kapalı mı?"},"Free of cracks, chips and damage?":{"es":"¿Sin grietas, astillas ni daños?","pt":"Sem rachaduras, lascas ou danos?","tr":"Çatlak, kırık veya hasar yok mu?"},"Promotional credit quoted ($)":{"es":"Crédito promocional cotizado ($)","pt":"Crédito promocional informado ($)","tr":"Teklif edilen promosyon kredisi ($)"},"Amount actually quoted to the customer; may differ from today's offer.":{"es":"Importe indicado al cliente; puede diferir de la oferta actual.","pt":"Valor informado ao cliente; pode diferir da oferta atual.","tr":"Müşteriye verilen tutar, güncel tekliften farklı olabilir."},"Rep / initials (optional)":{"es":"Vendedor / iniciales (opcional)","pt":"Vendedor / iniciais (opcional)","tr":"Temsilci / baş harfler (isteğe bağlı)"},"Additional notes (optional)":{"es":"Notas adicionales (opcional)","pt":"Notas adicionais (opcional)","tr":"Ek notlar (isteğe bağlı)"},"Clear form":{"es":"Borrar formulario","pt":"Limpar formulário","tr":"Formu temizle"},"Print Trade-In Record":{"es":"Imprimir registro","pt":"Imprimir registro de troca","tr":"Takas kaydını yazdır"},"Estimated device trade value:":{"es":"Valor estimado del teléfono:","pt":"Valor estimado do aparelho:","tr":"Tahmini takas değeri:"},"Not verified — check official trade-in tool":{"es":"Sin verificar; consulte la herramienta oficial","pt":"Não verificado; consulte a ferramenta oficial","tr":"Doğrulanmadı; resmi araçtan kontrol edin"},"Select a trade phone to check":{"es":"Seleccione un teléfono","pt":"Selecione um celular","tr":"Bir telefon seçin"},"No customer details are stored in GTT.":{"es":"GTT no guarda datos del cliente.","pt":"O GTT não armazena dados do cliente.","tr":"GTT müşteri bilgilerini saklamaz."}});
